def correlate(records,operation_id):
    if not isinstance(operation_id,str) or not operation_id or not isinstance(records,list):raise ValueError('explicit trace scope required')
    seen=set()
    for row in records:
        if not isinstance(row,dict) or any(not isinstance(row.get(k),str) for k in ('operation_id','span_id','parent_id')) or not row['operation_id'] or not row['span_id']:raise ValueError('normalized span identity required')
        key=(row['operation_id'],row['span_id'])
        if key in seen:raise ValueError('duplicate span within operation')
        seen.add(key)
    selected=[row for row in records if row['operation_id']==operation_id]
    spans={row['span_id']:row for row in selected};done=set()
    for ident in spans:
        chain=set();cursor=ident
        while cursor in spans and cursor not in done:
            if cursor in chain:raise ValueError('cyclic parent chain')
            chain.add(cursor);cursor=spans[cursor]['parent_id']
        done.update(chain)
    roots=sorted(i for i,row in spans.items() if not row['parent_id'])
    orphans=sorted(i for i,row in spans.items() if row['parent_id'] and row['parent_id'] not in spans)
    edges=sorted([row['parent_id'],i] for i,row in spans.items() if row['parent_id'] in spans)
    return {'operation_id':operation_id,'roots':roots,'edges':edges,'orphans':orphans}
