def audit_diagnostics(resources,settings,workspace):
    def rid(value):
        if not isinstance(value,str) or not value:raise ValueError('resource ID required')
        return value.casefold()
    destination=rid(workspace);inventory={}
    for resource in resources:
        key=rid(resource['id'])
        if key in inventory:raise ValueError('duplicate scoped resource')
        required=resource['required'];supported=resource['supported'];groups=resource['groups']
        if not isinstance(required,list) or any(not isinstance(i,str) or not i for i in required) or len(required)!=len(set(required)):raise ValueError('unique required categories')
        if supported is not None and (not isinstance(supported,list) or any(not isinstance(i,str) or not i for i in supported) or len(supported)!=len(set(supported))):raise ValueError('invalid capability projection')
        if not isinstance(groups,dict):raise ValueError('category group map required')
        if supported is not None:
            for members in groups.values():
                if not isinstance(members,list) or any(m not in supported for m in members):raise ValueError('group outside provider capabilities')
        inventory[key]=resource
    covered={key:set() for key in inventory}
    for setting in settings:
        key=rid(setting['resource_id'])
        if key not in inventory:raise ValueError('setting outside audited resources')
        selected=rid(setting['workspace_id'])==destination;resource=inventory[key]
        for log in setting['logs']:
            if type(log['enabled']) is not bool or ('category' in log)==('category_group' in log):raise ValueError('explicit category/group and boolean state required')
            if resource['supported'] is None:continue
            categories=resource['groups'].get(log['category_group']) if 'category_group' in log else [log['category']]
            if categories is None:raise ValueError('unknown category group')
            if selected and log['enabled']:covered[key].update(set(categories)&set(resource['supported']))
    result=[]
    for key,resource in inventory.items():
        required=set(resource['required']);supported=resource['supported']
        if supported is None:known=set();missing=set();unsupported=set();unverified=required
        else:
            known=required&covered[key];unsupported=required-set(supported);missing=(required&set(supported))-known;unverified=set()
        result.append({'resource_id':resource['id'],'covered':sorted(known),'missing':sorted(missing),'unsupported':sorted(unsupported),'unverified':sorted(unverified),'scope_complete':supported is not None and not missing and not unsupported,'evidence':'configuration-only'})
    return sorted(result,key=lambda row:row['resource_id'].casefold())
